// Scope decision (Nelson, via Edu, 2026-08-25): only Water Point audits are
// in active use right now, not Water Tanks. WATER_ASSET_ROWS above still
// holds all 1,717 assets (both types) so nothing has to be re-exported if
// that changes — this filter is the only thing keeping the 24 Water Tanks
// out of the Ward/Village/Sub-Village/Asset Tag picker. Drop the
// `.filter(...)` below to bring tanks back (WATER_TANK_SECTIONS in
// checklists.js is already there, ready to go).
const WATER_ASSETS = WATER_ASSET_ROWS
  .filter(r => r[1] === "P")
  .map(r => ({
    tag: r[0], type: r[1], ward: r[2], village: r[3], sub: r[4], loc: r[5],
  }));

/* ==================================================================
   LOOKUPS for the cascading Ward -> Village -> Sub-Village -> Asset Tag
   picker on the water_point setup screen. Sub-Village is optional: pass
   "" (or omit) to match assets regardless of sub-village.
   ================================================================== */
function uniqSorted(values){
  return Array.from(new Set(values)).sort((a,b) => a.localeCompare(b));
}

function getWards(){
  return uniqSorted(WATER_ASSETS.map(a => a.ward).filter(Boolean));
}
function getVillages(ward){
  if(!ward) return [];
  return uniqSorted(WATER_ASSETS.filter(a => a.ward === ward).map(a => a.village).filter(Boolean));
}
function getSubVillages(ward, village){
  if(!ward || !village) return [];
  return uniqSorted(
    WATER_ASSETS.filter(a => a.ward === ward && a.village === village).map(a => a.sub).filter(Boolean)
  );
}
/** Asset Tag options for the current Ward/Village (+ optional Sub-Village). */
function getAssets(ward, village, subVillage){
  if(!ward || !village) return [];
  return WATER_ASSETS
    .filter(a => a.ward === ward && a.village === village && (!subVillage || a.sub === subVillage))
    .sort((a,b) => a.tag.localeCompare(b.tag));
}
function findAsset(tag){
  return WATER_ASSETS.find(a => a.tag === tag) || null;
}

export { WATER_ASSETS, getWards, getVillages, getSubVillages, getAssets, findAsset };
